-- Generated by research/advtext2sql/delivery/build.py from the live
-- benchmark server; types, keys and column comments are the server's own.

CREATE TABLE "callcenterlogs" (
    "Date received" date,
    "Complaint ID" text,
    "rand client" text,
    "phonefinal" text,
    "vru+line" text,
    "call_id" bigint,
    "priority" bigint,
    "type" text,
    "outcome" text,
    "server" text,
    "ser_start" text,
    "ser_exit" text,
    "ser_time" text
);

CREATE TABLE "client" (
    "client_id" text NOT NULL,
    "sex" text,
    "day" bigint,
    "month" bigint,
    "year" bigint,
    "age" bigint,
    "social" text,
    "first" text,
    "middle" text,
    "last" text,
    "phone" text,
    "email" text,
    "address_1" text,
    "address_2" text,
    "city" text,
    "state" text,
    "zipcode" bigint,
    "district_id" bigint,
    PRIMARY KEY ("client_id")
);

CREATE TABLE "district" (
    "district_id" bigint NOT NULL,
    "city" text,
    "state_abbrev" text,
    "division" text,
    PRIMARY KEY ("district_id")
);

CREATE TABLE "events" (
    "Date received" date,
    "product" text,
    "Sub-product" text,
    "issue" text,
    "Sub-issue" text,
    "Consumer complaint narrative" text,
    "tags" text,
    "Consumer consent provided?" text,
    "Submitted via" text,
    "Date sent to company" text,
    "Company response to consumer" text,
    "Timely response?" text,
    "Consumer disputed?" text,
    "Complaint ID" text,
    "client_id" text
);

CREATE TABLE "reviews" (
    "date" date,
    "stars" bigint,
    "reviews" text,
    "product" text,
    "district_id" bigint
);

CREATE TABLE "state" (
    "statecode" text,
    "state" text,
    "region" text
);

ALTER TABLE "client" ADD FOREIGN KEY ("district_id") REFERENCES "district" ("district_id");
ALTER TABLE "events" ADD FOREIGN KEY ("client_id") REFERENCES "client" ("client_id");
ALTER TABLE "reviews" ADD FOREIGN KEY ("district_id") REFERENCES "district" ("district_id");
